    // import graph, so SEA Forge neither reimplements namespace/relative/std
    // resolution nor trusts an authored import spelling. ──
    let sources: BTreeMap<String, String> = source_set
        .files
        .iter()
        .map(|f| (f.uri.clone(), f.content.clone()))
        .collect();
